impl Document {
    pub(crate) fn compare_application_array_element(
        &self,
        other: &Document,
        a: &ApplicationArrayElement,
        b: &ApplicationArrayElement,
        path: &str,
    ) -> Result<(), String> {
        self.compare_application_composite_element_data_prototype(other, a.base(), b.base(), path)?;
        if a.get_array_size_handling() != b.get_array_size_handling() {
            return Err(format!("{path}: ARRAY_SIZE_HANDLING mismatch"));
        }
        if a.get_array_size_semantics() != b.get_array_size_semantics() {
            return Err(format!("{path}: ARRAY_SIZE_SEMANTICS mismatch"));
        }
        if a.get_index_data_type_ref() != b.get_index_data_type_ref() {
            return Err(format!("{path}: INDEX_DATA_TYPE_REF mismatch"));
        }
        if a.get_max_number_of_elements() != b.get_max_number_of_elements() {
            return Err(format!("{path}: MAX_NUMBER_OF_ELEMENTS mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_application_composite_element_data_prototype(
        &self,
        other: &Document,
        a: &ApplicationCompositeElementDataPrototype,
        b: &ApplicationCompositeElementDataPrototype,
        path: &str,
    ) -> Result<(), String> {
        self.compare_data_prototype(other, a.base(), b.base(), path)?;
        if a.get_type_t_ref() != b.get_type_t_ref() {
            return Err(format!("{path}: TYPE_T_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_application_record_element(
        &self,
        other: &Document,
        a: &ApplicationRecordElement,
        b: &ApplicationRecordElement,
        path: &str,
    ) -> Result<(), String> {
        self.compare_application_composite_element_data_prototype(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_is_optional() != b.get_is_optional() {
            return Err(format!("{path}: IS_OPTIONAL mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_autosar_data_prototype(
        &self,
        other: &Document,
        a: &AutosarDataPrototype,
        b: &AutosarDataPrototype,
        path: &str,
    ) -> Result<(), String> {
        self.compare_data_prototype(other, a.base(), b.base(), path)?;
        if a.get_type_t_ref() != b.get_type_t_ref() {
            return Err(format!("{path}: TYPE_T_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_data_prototype(
        &self,
        other: &Document,
        a: &DataPrototype,
        b: &DataPrototype,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_prototype(other, a.base(), b.base(), path)?;
        if a.get_sw_data_def_props() != b.get_sw_data_def_props() {
            return Err(format!("{path}: SW_DATA_DEF_PROPS mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_parameter_data_prototype(
        &self,
        other: &Document,
        a: &ParameterDataPrototype,
        b: &ParameterDataPrototype,
        path: &str,
    ) -> Result<(), String> {
        self.compare_autosar_data_prototype(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_init_value() != b.get_init_value() {
            return Err(format!("{path}: INIT_VALUE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_variable_data_prototype(
        &self,
        other: &Document,
        a: &VariableDataPrototype,
        b: &VariableDataPrototype,
        path: &str,
    ) -> Result<(), String> {
        self.compare_autosar_data_prototype(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_init_value() != b.get_init_value() {
            return Err(format!("{path}: INIT_VALUE mismatch"));
        }
        Ok(())
    }
}
